-- Reading B (population-wide): patients with a medication_lists entry naming a statin whose list_status is not 'discontinued' or
-- 'historical_inactive' (undated legacy snapshot rows and dated active list rows, original roster and population).
SELECT COUNT(DISTINCT patient) AS count FROM records WHERE stream='medication_lists' AND coalesce(json_extract(payload,'$.list_status'),'') NOT IN ('discontinued','historical_inactive') AND (lower(json_extract(payload,'$.name')) LIKE '%simvastatin%' OR lower(json_extract(payload,'$.name')) LIKE '%atorvastatin%' OR lower(json_extract(payload,'$.name')) LIKE '%rosuvastatin%' OR lower(json_extract(payload,'$.name')) LIKE '%pravastatin%' OR lower(json_extract(payload,'$.name')) LIKE '%lovastatin%' OR lower(json_extract(payload,'$.name')) LIKE '%pitavastatin%' OR lower(json_extract(payload,'$.name')) LIKE '%fluvastatin%');
